<?php
class ZCP_Platform_Multisite_Test extends WP_UnitTestCase{public function test_multisite(){ $this->assertTrue(is_multisite());}public function test_blog_context_restores(){$before=get_current_blog_id();$id=self::factory()->blog->create();switch_to_blog($id);restore_current_blog();$this->assertSame($before,get_current_blog_id());}public function test_network_policy_scope(){update_site_option('zcp_network_asset_policy',array('mode'=>'network_only'));$id=self::factory()->blog->create();switch_to_blog($id);$this->assertSame('network_only',get_site_option('zcp_network_asset_policy')['mode']);restore_current_blog();}public function test_security_scope_and_score(){$s=new ZinCelestial\Platform\Security\SecurityService();$r=$s->report();$this->assertArrayHasKey('network_id',$r['scope']);$this->assertGreaterThanOrEqual(0,$s->score($r));$this->assertLessThanOrEqual(100,$s->score($r));}}
